  "Wa": "function Wa(n, e, t, i, s = {}) {\n  let o = it(n, t);\n  let r = s.from || 0;\n  let a = s.fall || 1;\n  for (let l = 0; l < i; l++) {\n    let c = r + (t - r - 0.02) * Math.pow(e(), a);\n    let u = Math.round(c * n);\n    let f = Math.round(Dt(e, s.minLen || 0.001, s.maxLen || 0.004) * n);\n    let h = Dt(e, 0.2, 1) * (s.ampFall ? Math.exp(-c / s.ampFall) : 1);\n    for (let p = 0; p < f && u + p < o.length; p++)\n      o[u + p] += (e() * 2 - 1) * h * Math.exp((-4 * p) / f);\n  }\n  if (s.hp) {\n    kt(o, \"hp\", s.hp, 0.707, n);\n  }\n  if (s.lp) {\n    kt(o, \"lp\", s.lp, 0.707, n);\n  }\n  if (s.bp) {\n    kt(o, \"bp\", s.bp, s.q || 1, n);\n  }\n  return o;\n}",
  "t5": "function t5(n, e, t) {\n  let i = n.length - e;\n  let s = new Float32Array(e);\n  s.set(n.subarray(0, e));\n  for (let o = 0; o < i; o++) {\n    let r = (o + 0.5) / i;\n    let a = t ? Math.sin((r * Math.PI) / 2) : r;\n    let l = t ? Math.cos((r * Math.PI) / 2) : 1 - r;\n    s[o] = n[o] * a + n[e + o] * l;\n  }\n  return s;\n}",
