  "Fn": "function Fn(n, e, t, i = {}) {\n  let s = 0.004;\n  for (let a of t) s = Math.max(s, a[1]);\n  let o = it(n, Math.min(0.5, s * 7 + 0.004));\n  let r = i.jit == null ? 0.02 : i.jit;\n  Se(\n    o,\n    Xt(\n      n,\n      o.length / n,\n      t.map(([a, l, c]) => [a * (1 + (e() * 2 - 1) * r), l, c]),\n      e,\n    ),\n    0,\n    i.ring == null ? 0.6 : i.ring,\n    n,\n  );\n  if (i.tick !== 0) {\n    Se(\n      o,\n      xt(n, e, 0.006, i.tickTau || 9e-4, {\n        hp: i.hp || 2500,\n      }),\n      0,\n      i.tick == null ? 0.7 : i.tick,\n      n,\n    );\n  }\n  return o;\n}",
