  "$a": "function $a(n, e, t, i, s, o = 3) {\n  let r = [];\n  let a = (l, c, u, f) => {\n    for (let h = 0; h <= o; h++) {\n      let p = f + ((h / o) * Math.PI) / 2;\n      r.push([l + Math.cos(p) * u, c + Math.sin(p) * u]);\n    }\n  };\n  a(-n + s, e + s, s, Math.PI);\n  a(n - s, e + s, s, Math.PI * 1.5);\n  a(n - i, t - i, i, 0);\n  a(-n + i, t - i, i, Math.PI / 2);\n  return r;\n}",
