  "Zz": "function Zz(n) {\n  let e = n.attributes.position.array;\n  let t = n.attributes.normal.array;\n  let i = n.attributes.color.array;\n  let s = n.attributes.aSurf.array;\n  let o = (r, a, l, c) => {\n    for (let u = 0; u < c; u++) {\n      let f = r[a * c + u];\n      r[a * c + u] = r[l * c + u];\n      r[l * c + u] = f;\n    }\n  };\n  for (let r = 0; r < e.length / 3; r += 3) {\n    o(e, r + 1, r + 2, 3);\n    o(t, r + 1, r + 2, 3);\n    o(i, r + 1, r + 2, 3);\n    o(s, r + 1, r + 2, 4);\n  }\n}",
  "en": "function en(n, e, t, i = n.w, s = n.z) {\n  let o = n.x - e;\n  let r = n.v;\n  if (s >= 0.999) {\n    let a = Math.exp(-i * t);\n    let l = r + i * o;\n    n.x = e + (o + l * t) * a;\n    n.v = (r - i * l * t) * a;\n  } else {\n    let a = i * Math.sqrt(1 - s * s);\n    let l = Math.exp(-s * i * t);\n    let c = Math.cos(a * t);\n    let u = Math.sin(a * t);\n    let f = (r + s * i * o) / a;\n    n.x = e + l * (o * c + f * u);\n    n.v = l * (a * (f * c - o * u) - s * i * (o * c + f * u));\n  }\n  return n.x;\n}",
