  "WE": "function WE(n, e, t, i) {\n  let s = n * 3;\n  let o = n * 9;\n  let r = n * 8;\n  let a = e - m5[s];\n  let l = t - m5[s + 1];\n  let c = i - m5[s + 2];\n  let u = a * aa[o] + l * aa[o + 1] + c * aa[o + 2];\n  let f = a * aa[o + 3] + l * aa[o + 4] + c * aa[o + 5];\n  let h = a * aa[o + 6] + l * aa[o + 7] + c * aa[o + 8];\n  let p = VE[n];\n  if (p === vy) {\n    let E = pi[r];\n    let M = pi[r + 1];\n    let _ = u * pi[r + 3];\n    let T = Math.sqrt(_ * _ + f * f);\n    let w = -h;\n    let S = pi[r + 4];\n    let R = pi[r + 5];\n    let z = w * R - T * S;\n    let I =\n      z < 0\n        ? Math.sqrt(T * T + w * w) - M\n        : z > R * E\n          ? Math.sqrt(T * T + (w - E) * (w - E)) - pi[r + 2]\n          : T * R + w * S - M;\n    k1 = Math.max(I, pi[r + 6] - w, w - E + pi[r + 7]);\n    return I;\n  }\n  if (p === yy) {\n    let E = u * pi[r];\n    let M = f * pi[r + 1];\n    let _ = h * pi[r + 2];\n    let T = Math.sqrt(E * E + M * M + _ * _);\n    if (T < 1e-9) return (k1 = -pi[r + 3]);\n    let w = E * pi[r];\n    let S = M * pi[r + 1];\n    let R = _ * pi[r + 2];\n    return (k1 = (T * (T - 1)) / Math.sqrt(w * w + S * S + R * R));\n  }\n  let d = pi[r + 3];\n  let m = Math.abs(u) - pi[r] + d;\n  let x = Math.abs(f) - pi[r + 1] + d;\n  let v = Math.abs(h) - pi[r + 2] + d;\n  let y = m > 0 ? m : 0;\n  let b = x > 0 ? x : 0;\n  let g = v > 0 ? v : 0;\n  return (k1 =\n    Math.sqrt(y * y + b * b + g * g) + Math.min(Math.max(m, x, v), 0) - d);\n}",
