  "dD": "function dD(n) {\n  if (n <= Pu[0]) return [Math.max(0.3, 1 + (n - Pu[0]) / 0.016), A1[0]];\n  for (let e = 0; e < 3; e++)\n    if (n <= Pu[e + 1]) {\n      let t = (n - Pu[e]) / (Pu[e + 1] - Pu[e]);\n      return [1 + e + t, A1[e] + (A1[e + 1] - A1[e]) * t];\n    }\n  return [Math.min(4.7, 4 + (n - Pu[3]) / 0.016), A1[3]];\n}",
  "pD": "function pD(n, e, t, i) {\n  let s = 1e9;\n  for (let o = 0; o < 3; o++) {\n    let r = Dr(n, o);\n    let a = Dr(n, o + 1);\n    let l = a.x - r.x;\n    let c = a.y - r.y;\n    let u = a.z - r.z;\n    let f = l * l + c * c + u * u;\n    let h = ((e - r.x) * l + (t - r.y) * c + (i - r.z) * u) / f;\n    h = Math.max(o === 0 ? -0.5 : 0, Math.min(1, h));\n    let p = e - r.x - l * h;\n    let d = t - r.y - c * h;\n    let m = i - r.z - u * h;\n    let x = Math.hypot(p, d, m);\n    if (x < s) {\n      s = x;\n      let v = Lr(n, o, 0);\n      let y = Lr(n, o, 1);\n      let b = x || 1;\n      R1[0] =\n        (o > 0 ? t0[n].len[0] : 0) +\n        (o > 1 ? t0[n].len[1] : 0) +\n        h * t0[n].len[o];\n      R1[1] = (p * y.x + d * y.y + m * y.z) / b;\n      R1[2] = (p * v.x + d * v.y + m * v.z) / b;\n    }\n  }\n  R1[3] = s;\n  return R1;\n}",
